function getInvideoTranslation(key, lang) {
    if (invideoTranslations[lang] && invideoTranslations[lang][key]) {
        return invideoTranslations[lang][key];
    }
    if (invideoTranslations.en && invideoTranslations.en[key]) {
        return invideoTranslations.en[key];
    }
    return null;
}

function applyInvideoTranslations(lang) {
    console.log('🔥 Applying invideo translations for:', lang);
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && (key.startsWith('review.invideo.') || key.startsWith('review.common.'))) {
            const translation = getInvideoTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    console.log(`✅ Applied ${count} invideo translations`);
}

document.addEventListener('languageChanged', (e) => {
    setTimeout(() => applyInvideoTranslations(e.detail.language), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        applyInvideoTranslations(window.i18n ? window.i18n.getCurrentLanguage() : 'en');
    });
} else {
    applyInvideoTranslations(window.i18n ? window.i18n.getCurrentLanguage() : 'en');
}

console.log('✅ invideo i18n loaded');
